import java.util.Scanner;

class LibraryItem {
    protected String title;
    protected String code;

    LibraryItem(String title, String code) {
        this.title = title;
        this.code = code;
    }

    String getSummary() {
        return title + " (" + code + ")";
    }
}

class Book extends LibraryItem {
    Book(String title, String code) {
        super(title, code);
    }

    @Override
    String getSummary() {
        return "Buku: " + super.getSummary();
    }
}

class Journal extends LibraryItem {
    Journal(String title, String code) {
        super(title, code);
    }

    @Override
    String getSummary() {
        return "Jurnal: " + super.getSummary();
    }
}

class DigitalItem extends LibraryItem {
    DigitalItem(String title, String code) {
        super(title, code);
    }

    @Override
    String getSummary() {
        return "Digital: " + super.getSummary();
    }
}

class LibraryItemFactory {
    // create(type, title, code): "buku" -> Book, "jurnal" -> Journal, "digital" -> DigitalItem. Jenis lain: lempar IllegalArgumentException dengan pesan "Jenis tidak dikenal: <type>".
    static LibraryItem create(String type, String title, String code) {
        return null;
    }
}

// Jadikan ItemRegistry sebuah Singleton: constructor private, satu instance statis, getInstance() selalu mengembalikan instance yang sama. Method add(item) menambah hitungan, count() mengembalikannya.
class ItemRegistry {
    private int count;

    static ItemRegistry getInstance() {
        return new ItemRegistry();
    }

    void add(LibraryItem item) {
        count++;
    }

    int count() {
        return count;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        ItemRegistry registry = ItemRegistry.getInstance();
        while (in.hasNextLine()) {
            String line = in.nextLine().trim();
            if (line.equals("selesai")) {
                break;
            }
            String[] p = line.split(";");
            try {
                LibraryItem item = LibraryItemFactory.create(p[0].trim(), p[1].trim(), p[2].trim());
                registry.add(item);
                System.out.println(item.getSummary());
            } catch (IllegalArgumentException e) {
                System.out.println(e.getMessage());
            }
        }
        System.out.println("Total item: " + registry.count());
        System.out.println("Instance sama: " + (ItemRegistry.getInstance() == ItemRegistry.getInstance()));
    }
}
